"""Lot 1 : Kadiogo, Guiriko, Bankui, Yaadga."""
from tales_kit import art, choice, gloss, it, quiz, scene, tale

# ------------------------------------------------------------------ Kadiogo
tale(34, "wogdgo-la-ou-l-on-recoit-le-respect", type="legende", region="kadiogo", place="Ouagadougou",
     coords=(12.37, -1.52), people="Mossi", language="moore", duration=5, age=8,
     tags=["fondation", "royaume", "respect", "histoire"], featured=True, cover=3,
     fr=("Wogdgo, là où l'on reçoit le respect", "La naissance de Ouagadougou",
         "Le village s'appelait Kumbee-Tenga et ses habitants vivaient dans la peur. Un jeune chef mossi, Oubri, petit-fils de Ouédraogo, change son destin et son nom.",
         "Le respect se gagne par la protection qu'on offre aux autres, non par la peur qu'on inspire."),
     en=("Wogdgo, Where Respect Is Received", "The birth of Ouagadougou",
         "The village was called Kumbee-Tenga and its people lived in fear. A young Mossi chief, Oubri, grandson of Ouédraogo, changed its fate and its name.",
         "Respect is earned by the protection you give others, not by the fear you inspire."),
     scenes=[
         scene(art("dawn", "village", it("sun", 16, 240), it("hut", 26, 26), it("hut", 72, 30, 0.8), it("man-talk", 44, c="#7C3109"), it("woman", 56)),
               "Il y a très longtemps, au cœur du plateau, se trouvait un village que l'on appelait Kumbee-Tenga. Les Yonyonsé, qui y vivaient, étaient sans cesse inquiétés par les Ninsi, plus puissants qu'eux. Personne ne dormait tranquille.",
               "A very long time ago, in the heart of the plateau, there was a village called Kumbee-Tenga. The Yonyonsé who lived there were constantly troubled by the Ninsi, who were stronger than they were. No one slept in peace."),
         scene(art("day", "savanna", it("sun", 82, 300), it("rider", 30), it("horse", 46, s=0.9), it("king", 64, c="#2F3E6B"), it("acacia", 88, 26)),
               "Un jour arriva Oubri, fils de Zoungrana et petit-fils de Ouédraogo, l'enfant de la princesse Yennenga. Il venait de Tenkodogo avec ses cavaliers. Les anciens du village allèrent à sa rencontre et lui demandèrent sa protection.",
               "One day Oubri arrived, son of Zoungrana and grandson of Ouédraogo, the child of Princess Yennenga. He came from Tenkodogo with his horsemen. The village elders went to meet him and asked for his protection.",
               choice(("Que doit faire Oubri ?", "What should Oubri do?"),
                      [("Protéger le village", "Protect the village"), ("Repartir chez lui", "Go back home")], 0,
                      ("Oubri promit de défendre ceux qui l'avaient accueilli…", "Oubri promised to defend those who had welcomed him…"))),
         scene(art("dusk", "savanna", it("rider", 24), it("horse-run", 40, s=0.9), it("spear", 58), it("man-up", 70, c="#7C3109"), it("cloud", 80, 270)),
               "Oubri et ses compagnons affrontèrent les Ninsi et les éloignèrent du village. Pour la première fois depuis longtemps, les enfants purent jouer sans crainte et les femmes aller au marigot sans se cacher.",
               "Oubri and his companions confronted the Ninsi and drove them away from the village. For the first time in a long while, children could play without fear and women could go to the stream without hiding."),
         scene(art("day", "village", it("sun", 84, 300), it("palace", 50, 34, 0.9), it("king-talk", 30, c="#2F3E6B"), it("man", 66), it("woman-up", 76), it("drum", 14)),
               "On donna au lieu un nouveau nom : Wogdgo, « là où l'on reçoit l'honneur et le respect ». Avec le temps, les Français l'écrivirent Ouagadougou. Aujourd'hui encore, c'est la capitale du pays et la cour du Moogho Naaba, héritier d'Oubri.",
               "The place was given a new name: Wogdgo, \"where honour and respect are received\". In time the French wrote it Ouagadougou. To this day it is the country's capital and the court of the Moogho Naaba, Oubri's heir."),
     ],
     quizzes=[
         quiz(("Comment s'appelait le village avant Oubri ?", "What was the village called before Oubri?"),
              [("Kumbee-Tenga", "Kumbee-Tenga"), ("Tenkodogo", "Tenkodogo"), ("Gambaga", "Gambaga")], 0),
         quiz(("Que veut dire Wogdgo ?", "What does Wogdgo mean?"),
              [("Là où l'on reçoit le respect", "Where respect is received"), ("La grande rivière", "The great river"), ("La terre rouge", "The red earth")], 0),
     ],
     glossary=[gloss("Moogho Naaba", "moore", "Roi des Mossi de Ouagadougou, « chef du monde mossi ».", "King of the Mossi of Ouagadougou, \"chief of the Mossi world\".")],
     source=("Tradition orale mossi sur la fondation de Ouagadougou par Naaba Oubri (Kumbee-Tenga devenu Wogodogo), rapportée notamment par Sidwaya et les historiques des royaumes mossi. Les dates varient selon les sources. Mise en récit libre.",
             "Mossi oral tradition on the founding of Ouagadougou by Naaba Oubri (Kumbee-Tenga renamed Wogodogo), reported by Sidwaya and histories of the Mossi kingdoms. Dates vary between sources. Free retelling."))

tale(35, "les-crocodiles-de-bazoule", type="legende", region="kadiogo", place="Bazoulé",
     coords=(12.33, -1.75), people="Mossi", language="moore", duration=4, age=6,
     tags=["crocodiles", "sécheresse", "pacte", "lieu sacré"],
     fr=("Les crocodiles de Bazoulé", "La mare de l'alliance",
         "Pendant une terrible sécheresse, des crocodiles conduisent les habitants assoiffés jusqu'à une eau cachée. Depuis, à Bazoulé, l'homme et le crocodile vivent en paix.",
         "Celui qui t'a sauvé dans la détresse mérite ton respect pour toujours."),
     en=("The Crocodiles of Bazoulé", "The pond of the alliance",
         "During a terrible drought, crocodiles lead the thirsty villagers to hidden water. Ever since, in Bazoulé, people and crocodiles have lived in peace.",
         "Whoever saved you in your hour of need deserves your respect for ever."),
     scenes=[
         scene(art("day", "sahel", it("sun", 80, 320, 1.4), it("baobab", 14, 26, c="bare"), it("woman", 40), it("jar", 48), it("child", 56), it("field", 78, 20, 0.6, c="dry")),
               "Il y a plusieurs siècles, la pluie oublia le village de Bazoulé. Les puits se vidèrent, les champs brûlèrent et les femmes marchaient des heures sans trouver une goutte d'eau.",
               "Several centuries ago, the rain forgot the village of Bazoulé. The wells ran dry, the fields burned and the women walked for hours without finding a drop of water."),
         scene(art("dusk", "savanna", it("croc", 56, s=1.2), it("hunter", 30), it("bush", 74, 10), it("grass", 44)),
               "Un soir, des chasseurs épuisés virent des crocodiles sortir de la brousse et s'éloigner lentement, toujours dans la même direction. Ces bêtes ne cherchaient pas à attaquer : elles semblaient montrer un chemin.",
               "One evening, exhausted hunters saw crocodiles come out of the bush and move slowly away, always in the same direction. The animals did not try to attack: they seemed to be showing a path.",
               choice(("Que doivent faire les chasseurs ?", "What should the hunters do?"),
                      [("Suivre les crocodiles", "Follow the crocodiles"), ("Les chasser", "Hunt them")], 0,
                      ("Ils les suivirent à distance, le cœur battant…", "They followed them from a distance, hearts pounding…"))),
         scene(art("dawn", "lake", it("sun", 18, 240), it("croc", 62), it("croc", 40, s=0.8), it("hunter", 20), it("palm", 86, 30)),
               "À l'aube, les crocodiles plongèrent dans une mare cachée, pleine d'eau fraîche. Les chasseurs coururent prévenir le village : tout le monde put boire, abreuver les bêtes et sauver les semences.",
               "At dawn, the crocodiles slid into a hidden pond full of fresh water. The hunters ran to tell the village: everyone could drink, water the animals and save the seeds."),
         scene(art("day", "lake", it("sun", 84, 300), it("croc", 50, s=1.1), it("child", 30), it("chicken", 70), it("elder", 18)),
               "Les anciens firent un pacte : on ne tuerait jamais un crocodile de la mare. Aujourd'hui encore, les habitants les nourrissent de poulets et les enfants s'assoient près d'eux sans crainte. Pour Bazoulé, ils sont l'âme des ancêtres.",
               "The elders made a pact: no one would ever kill a crocodile of the pond. To this day the villagers feed them chickens and children sit near them without fear. For Bazoulé, they are the souls of the ancestors."),
     ],
     quizzes=[
         quiz(("Qui a conduit les habitants vers l'eau ?", "Who led the villagers to the water?"),
              [("Des crocodiles", "Crocodiles"), ("Un lion", "A lion"), ("Des oiseaux", "Birds")], 0),
         quiz(("Que donne-t-on aux crocodiles aujourd'hui ?", "What are the crocodiles given today?"),
              [("Des poulets", "Chickens"), ("Du mil", "Millet"), ("Du lait", "Milk")], 0),
     ],
     glossary=[gloss("totem", "fr", "Animal sacré d'une famille ou d'un village, qu'on ne doit ni tuer ni manger.", "A sacred animal of a family or village, which must be neither killed nor eaten.")],
     source=("Légende de la mare aux crocodiles sacrés de Bazoulé (province du Kadiogo), rapportée par la presse et les guides de voyage (Africa24, Le360, Routard). Les versions et les dates varient. Mise en récit libre.",
             "Legend of the sacred crocodile pond of Bazoulé (Kadiogo province), reported by the press and travel guides (Africa24, Le360, Routard). Versions and dates vary. Free retelling."))

# ------------------------------------------------------------------ Guiriko
tale(36, "sya-la-vendeuse-de-dolo", type="legende", region="guiriko", place="Bobo-Dioulasso",
     coords=(11.18, -4.30), people="Bobo", language="dioula", duration=5, age=7,
     tags=["fondation", "générosité", "ville", "hospitalité"], featured=True, cover=2,
     fr=("Sya, la vendeuse de dolo", "Aux origines de Bobo-Dioulasso",
         "Au bord du Houet, une jeune femme accueille tous les voyageurs avec la même bonté. Son nom deviendra celui de la ville : Sya, « la paix ».",
         "Là où l'on accueille l'étranger avec bonté, la paix finit par s'installer."),
     en=("Sya, the Dolo Seller", "The origins of Bobo-Dioulasso",
         "On the banks of the Houet, a young woman welcomes every traveller with the same kindness. Her name will become the town's: Sya, \"peace\".",
         "Where strangers are welcomed with kindness, peace eventually settles."),
     scenes=[
         scene(art("day", "river", it("sun", 82, 300), it("woman", 36, c="#E69135"), it("jar", 46), it("calabash", 52), it("palm", 14, 30), it("hut", 74, 26)),
               "Il y a très longtemps, entre les rivières Houet et Sanyon, une jeune femme nommée Sya vendait du dolo, la bière de mil. Sa case était au bord du chemin, et tout voyageur pouvait s'y reposer.",
               "A very long time ago, between the Houet and Sanyon rivers, a young woman named Sya sold dolo, millet beer. Her hut stood by the path, and every traveller could rest there."),
         scene(art("dusk", "village", it("man", 26, c="#2F3E6B"), it("woman-talk", 44, c="#E69135"), it("calabash", 52), it("man-talk", 64, flip=True), it("hut", 82, 26)),
               "Chasseurs, marchands, bergers : Sya les accueillait tous, riches ou pauvres. Un soir, un voyageur sans un sou lui demanda à boire. Les autres se moquèrent de lui.",
               "Hunters, traders, herders: Sya welcomed them all, rich or poor. One evening a penniless traveller asked her for a drink. The others laughed at him.",
               choice(("Que va faire Sya ?", "What will Sya do?"),
                      [("Lui offrir à boire", "Offer him a drink"), ("Le renvoyer", "Send him away")], 0,
                      ("Sya lui tendit la calebasse en souriant : « Ici, chacun est le bienvenu. »", "Sya handed him the calabash with a smile: \"Here, everyone is welcome.\""))),
         scene(art("day", "village", it("sun", 16, 260), it("hut", 20, 26), it("hut", 36, 30, 0.8), it("granary", 52, 26, 0.8), it("mosque", 74, 34, 0.7), it("man", 88)),
               "La réputation de Sya traversa la savane. Des familles vinrent s'installer près d'elle, puis d'autres encore. Le campement devint un village, puis une ville : on l'appela Sya, ce qui signifierait « la paix, le bonheur ».",
               "Sya's reputation crossed the savannah. Families came to settle near her, then more and more. The camp became a village, then a town: it was called Sya, which is said to mean \"peace, happiness\"."),
         scene(art("day", "village", it("sun", 84, 300), it("mosque", 50, 34, 0.9), it("woman-up", 24), it("child-up", 34), it("drum", 70), it("man-up", 80)),
               "Des siècles plus tard, Sya devint Bobo-Dioulasso, « la maison des Bobo et des Dioula ». Le vieux quartier de Dioulassoba garde le souvenir de ses débuts, et la ville reste connue pour son accueil chaleureux.",
               "Centuries later, Sya became Bobo-Dioulasso, \"the home of the Bobo and the Dioula\". The old Dioulassoba quarter keeps the memory of its beginnings, and the town is still known for its warm welcome."),
     ],
     quizzes=[
         quiz(("Que vendait Sya ?", "What did Sya sell?"),
              [("Du dolo", "Dolo"), ("Du miel", "Honey"), ("Des pagnes", "Cloth")], 0),
         quiz(("Que signifierait le nom Sya ?", "What is Sya said to mean?"),
              [("La paix, le bonheur", "Peace, happiness"), ("La rivière", "The river"), ("La forêt", "The forest")], 0),
     ],
     glossary=[gloss("dolo", "fr", "Bière traditionnelle de mil ou de sorgho, préparée surtout par les femmes.", "Traditional millet or sorghum beer, mostly brewed by women.")],
     source=("Une des traditions sur l'origine de Sya, noyau de Bobo-Dioulasso (dossier UNESCO de la liste indicative, techno-science.net). D'autres versions existent (Kibidoué, Tiguisso). Mise en récit libre.",
             "One of the traditions about the origin of Sya, the core of Bobo-Dioulasso (UNESCO tentative list file, techno-science.net). Other versions exist (Kibidoué, Tiguisso). Free retelling."))

tale(37, "le-margouillat-qui-ne-savait-pas-dire-non", type="conte", region="guiriko", place="Houndé",
     coords=(11.50, -3.52), people="Bwaba", language="dioula", duration=3, age=4,
     tags=["animaux", "pourquoi", "franchise", "humour"], cover=1,
     fr=("Le margouillat qui ne savait pas dire non", "Pourquoi il hoche la tête",
         "Le margouillat voulait plaire à tout le monde et répondait « oui » à chacun. Jusqu'au jour où ses promesses se sont retournées contre lui.",
         "Savoir dire non avec respect vaut mieux que promettre ce qu'on ne peut pas tenir."),
     en=("The Lizard Who Couldn't Say No", "Why it nods its head",
         "The lizard wanted to please everyone and said \"yes\" to everybody. Until the day his promises turned against him.",
         "Knowing how to say no respectfully is better than promising what you cannot deliver."),
     scenes=[
         scene(art("day", "village", it("sun", 82, 300), it("lizard", 46, 10, 1.6), it("hut", 20, 26), it("granary", 74, 24, 0.8)),
               "Autrefois, le margouillat était l'ami de tous. Quand quelqu'un lui demandait un service, il répondait toujours : « Oui, oui, bien sûr ! » Il avait peur de fâcher les autres.",
               "Long ago, the lizard was everyone's friend. Whenever someone asked him a favour, he always answered: \"Yes, yes, of course!\" He was afraid of upsetting anyone."),
         scene(art("day", "savanna", it("lizard", 40, 6, 1.4), it("hare", 22), it("guinea-fowl", 60, s=1.2), it("tortoise", 78)),
               "Le lièvre lui demanda de garder ses arachides, la pintade de surveiller ses œufs, la tortue de l'aider à cultiver son champ. Le même jour, à la même heure ! Le margouillat dit oui à tous.",
               "The hare asked him to look after his groundnuts, the guinea fowl to watch her eggs, the tortoise to help farm his field. The same day, at the same time! The lizard said yes to all of them.",
               choice(("Que va-t-il se passer ?", "What will happen?"),
                      [("Il ne pourra tenir aucune promesse", "He won't keep any promise"), ("Tout ira bien", "All will be well")], 0,
                      ("Il courut partout… et n'arriva nulle part à temps.", "He ran everywhere… and got nowhere in time."))),
         scene(art("dusk", "savanna", it("lizard", 50, 6, 1.4), it("hare", 28, flip=True), it("guinea-fowl", 70, s=1.2, flip=True), it("tortoise", 84, flip=True)),
               "Les singes mangèrent les arachides, le serpent goba les œufs, et le champ de la tortue resta en friche. Tous vinrent se plaindre. Le margouillat, honteux, ne savait plus que dire.",
               "The monkeys ate the groundnuts, the snake swallowed the eggs, and the tortoise's field lay fallow. Everyone came to complain. The ashamed lizard no longer knew what to say."),
         scene(art("day", "rocks", it("sun", 84, 300), it("lizard", 46, 30, 1.6), it("rock", 46), it("bush", 80, 10)),
               "Depuis ce jour, quand on lui parle, le margouillat hoche la tête de haut en bas, encore et encore, comme s'il disait oui… mais il ne promet plus rien. Il réfléchit, au soleil, sur son rocher.",
               "Since that day, when someone speaks to him, the lizard nods his head up and down, again and again, as if saying yes… but he no longer promises anything. He thinks it over, in the sun, on his rock."),
     ],
     quizzes=[
         quiz(("Pourquoi le margouillat disait-il toujours oui ?", "Why did the lizard always say yes?"),
              [("Il avait peur de fâcher les autres", "He was afraid of upsetting others"), ("Il était très fort", "He was very strong"), ("Il était riche", "He was rich")], 0),
         quiz(("Que fait le margouillat aujourd'hui ?", "What does the lizard do today?"),
              [("Il hoche la tête", "He nods his head"), ("Il chante", "He sings"), ("Il court vite", "He runs fast")], 0),
     ],
     glossary=[gloss("margouillat", "fr", "Lézard des savanes au corps gris et à la tête orange, qui hoche souvent la tête.", "A savannah lizard with a grey body and an orange head, which often nods.")],
     source=("Conte étiologique populaire en Afrique de l'Ouest (le margouillat qui hoche la tête), raconté sous de nombreuses formes, notamment en pays bwaba et dioula. Version écrite pour KIBARE.",
             "A popular West African \"why\" tale (the nodding lizard), told in many forms, including in Bwaba and Dioula country. Version written for KIBARE."))

# ------------------------------------------------------------------ Bankui
tale(38, "la-chauve-souris-ni-oiseau-ni-bete", type="conte", region="bankui", place="Dédougou",
     coords=(12.46, -3.46), people="Bwaba", language="bwamu", duration=4, age=5,
     tags=["animaux", "pourquoi", "loyauté", "nuit"], cover=2,
     fr=("La chauve-souris, ni oiseau ni bête", "Pourquoi elle vole la nuit",
         "Pendant la guerre entre les oiseaux et les bêtes, la chauve-souris change de camp à chaque victoire. Quand la paix revient, plus personne ne veut d'elle.",
         "Qui change de camp au gré du vent finit seul."),
     en=("The Bat, Neither Bird Nor Beast", "Why it flies at night",
         "During the war between birds and beasts, the bat switches sides after every victory. When peace returns, nobody wants her any more.",
         "Those who change sides with the wind end up alone."),
     scenes=[
         scene(art("day", "savanna", it("sun", 82, 300), it("bird-small", 24, 40), it("guinea-fowl", 36, s=1.2), it("lion", 66, s=0.8, flip=True), it("hyena", 84, flip=True)),
               "Un jour, les oiseaux et les bêtes à quatre pattes se disputèrent la savane du Mouhoun. La dispute tourna à la guerre. Chacun devait choisir son camp.",
               "One day the birds and the four-legged beasts quarrelled over the savannah of the Mouhoun. The quarrel turned into war. Everyone had to choose a side."),
         scene(art("dusk", "savanna", it("bat", 50, 120, 1.6), it("lion", 74, s=0.8, flip=True), it("guinea-fowl", 24, s=1.2)),
               "La chauve-souris attendit. Quand les bêtes gagnaient, elle disait : « Regardez mes dents et mes poils, je suis des vôtres ! » Quand les oiseaux gagnaient : « Voyez mes ailes, je suis votre sœur ! »",
               "The bat waited. When the beasts were winning, she said: \"Look at my teeth and my fur, I'm one of you!\" When the birds were winning: \"See my wings, I'm your sister!\"",
               choice(("Est-ce une bonne idée ?", "Is that a good idea?"),
                      [("Non, il faut être loyal", "No, one must be loyal"), ("Oui, c'est malin", "Yes, it's clever")], 0,
                      ("La ruse ne dure qu'un temps…", "Trickery only lasts so long…"))),
         scene(art("day", "village", it("sun", 84, 300), it("lion", 30, s=0.8), it("guinea-fowl", 46, s=1.3), it("elephant", 72, s=0.7), it("bat", 50, 160, 1.2)),
               "La guerre finit et les deux camps firent la paix autour d'un grand repas. La chauve-souris voulut s'asseoir avec les oiseaux : ils la chassèrent. Elle alla vers les bêtes : elles lui tournèrent le dos.",
               "The war ended and both sides made peace over a great meal. The bat tried to sit with the birds: they chased her away. She went to the beasts: they turned their backs on her."),
         scene(art("night", "forest", it("moon", 76, 300), it("karite", 40, 20, 1.2), it("bat", 40, 150, 1.4), it("owl", 64, 110)),
               "Honteuse, la chauve-souris s'envola se cacher dans les arbres. Depuis ce jour, elle dort le jour, la tête en bas, et ne sort qu'à la nuit tombée, quand oiseaux et bêtes ne peuvent plus la voir.",
               "Ashamed, the bat flew off to hide in the trees. Since that day she sleeps by day, upside down, and only comes out at nightfall, when neither birds nor beasts can see her."),
     ],
     quizzes=[
         quiz(("Pourquoi la chauve-souris changeait-elle de camp ?", "Why did the bat keep switching sides?"),
              [("Pour être toujours avec les gagnants", "To always be with the winners"), ("Pour faire la paix", "To make peace"), ("Par erreur", "By mistake")], 0),
         quiz(("Quand sort la chauve-souris ?", "When does the bat come out?"),
              [("La nuit", "At night"), ("À midi", "At noon"), ("Jamais", "Never")], 0),
     ],
     glossary=[gloss("Mouhoun", "fr", "Le plus long fleuve du Burkina Faso, autrefois appelé Volta Noire.", "Burkina Faso's longest river, formerly called the Black Volta.")],
     source=("Conte étiologique répandu dans toute l'Afrique de l'Ouest (la chauve-souris entre oiseaux et bêtes), également connu dans la tradition ésopique. Version écrite pour KIBARE, située en pays bwaba.",
             "A \"why\" tale found throughout West Africa (the bat between birds and beasts), also known in the Aesopic tradition. Version written for KIBARE, set in Bwaba country."))

tale(39, "la-part-du-lion", type="conte", region="bankui", place="Boromo",
     coords=(11.75, -2.93), people="Marka", language="dioula", duration=4, age=6,
     tags=["animaux", "partage", "ruse", "justice"], cover=1,
     fr=("La part du lion", "Le partage de la chasse",
         "Le lion, la hyène et le chacal chassent ensemble dans la forêt des Deux Balés. Au moment du partage, le chacal trouve la seule réponse qui le garde en vie.",
         "Apprends de l'erreur des autres avant d'avoir à payer la tienne."),
     en=("The Lion's Share", "Dividing the hunt",
         "The lion, the hyena and the jackal hunt together in the Deux Balés forest. When the time comes to share, the jackal finds the only answer that keeps him alive.",
         "Learn from other people's mistakes before you have to pay for your own."),
     scenes=[
         scene(art("dawn", "forest", it("sun", 16, 240), it("lion", 34, s=0.9), it("hyena", 56), it("dog", 74, c="#C9822B"), it("karite", 90, 24)),
               "Dans la grande forêt des Deux Balés, près de Boromo, le lion proposa à la hyène et au chacal de chasser ensemble. « À trois, nous attraperons de grosses proies ! » Les deux autres acceptèrent, flattés.",
               "In the great Deux Balés forest near Boromo, the lion suggested to the hyena and the jackal that they hunt together. \"The three of us will catch big prey!\" The other two agreed, flattered."),
         scene(art("day", "savanna", it("sun", 82, 300), it("lion", 40, s=0.9), it("wild-cow", 60), it("hyena", 24), it("dog", 78, c="#C9822B")),
               "La chasse fut bonne : un buffle, une antilope et un lièvre. Le lion dit à la hyène : « Partage, toi. » La hyène, gourmande, répondit : « Le buffle pour toi, l'antilope pour moi, le lièvre pour le chacal. »",
               "The hunt went well: a buffalo, an antelope and a hare. The lion said to the hyena: \"You share it out.\" The greedy hyena answered: \"The buffalo for you, the antelope for me, the hare for the jackal.\"",
               choice(("Le lion sera-t-il content ?", "Will the lion be pleased?"),
                      [("Non, il veut tout", "No, he wants everything"), ("Oui, c'est juste", "Yes, it's fair")], 0,
                      ("Le lion rugit et chassa la hyène d'un coup de patte.", "The lion roared and drove the hyena off with a swipe of his paw."))),
         scene(art("dusk", "savanna", it("lion", 46, s=1), it("dog", 26, c="#C9822B"), it("antelope", 70), it("hare", 84)),
               "Le lion se tourna vers le chacal : « À toi de partager. » Le chacal salua bien bas : « Le buffle pour ton déjeuner, l'antilope pour ton dîner, le lièvre pour ton goûter. Tout est à toi, grand roi. »",
               "The lion turned to the jackal: \"Your turn to share.\" The jackal bowed low: \"The buffalo for your lunch, the antelope for your dinner, the hare for your snack. Everything is yours, great king.\""),
         scene(art("day", "forest", it("sun", 84, 300), it("lion", 60, s=0.9), it("dog", 30, c="#C9822B"), it("hyena", 14, flip=True)),
               "« Qui t'a appris à si bien partager ? » demanda le lion, satisfait. « La hyène », répondit le chacal. Et depuis, quand quelqu'un prend tout pour lui, on dit au pays marka qu'il a pris « la part du lion ».",
               "\"Who taught you to share so well?\" asked the satisfied lion. \"The hyena,\" replied the jackal. And since then, when someone takes everything for himself, people in Marka country say he took \"the lion's share\"."),
     ],
     quizzes=[
         quiz(("Qui a appris au chacal à partager ?", "Who taught the jackal to share?"),
              [("La hyène", "The hyena"), ("Le lion", "The lion"), ("Le lièvre", "The hare")], 0),
         quiz(("Où se passe ce conte ?", "Where does this tale take place?"),
              [("Dans la forêt des Deux Balés", "In the Deux Balés forest"), ("Au bord de la mer", "By the sea"), ("Dans une ville", "In a town")], 0),
     ],
     glossary=[gloss("Deux Balés", "fr", "Forêt classée près de Boromo, connue pour ses éléphants.", "A protected forest near Boromo, known for its elephants.")],
     source=("Fable de la « part du lion », connue dans les traditions africaines et ésopiques, racontée sous de nombreuses formes en Afrique de l'Ouest. Version écrite pour KIBARE, située en pays marka.",
             "The \"lion's share\" fable, known in African and Aesopic traditions and told in many forms across West Africa. Version written for KIBARE, set in Marka country."))

# ------------------------------------------------------------------ Yaadga
tale(40, "ouahigouya-venez-vous-prosterner", type="recit", region="yaadga", place="Ouahigouya",
     coords=(13.58, -2.42), people="Mossi", language="moore", duration=5, age=8,
     tags=["royaume", "Yatenga", "histoire", "fondation"], cover=3,
     fr=("Ouahigouya, « venez vous prosterner »", "Naaba Kango, le roi-lion du Yatenga",
         "Après des années d'exil, Naaba Kango reprend le trône du Yatenga et fonde une nouvelle capitale. Son appel aux chefs des alentours donne son nom à la ville.",
         "Un pouvoir solide se construit en rassemblant, pas seulement en commandant."),
     en=("Ouahigouya, \"Come and Bow Down\"", "Naaba Kango, the lion-king of Yatenga",
         "After years in exile, Naaba Kango regains the throne of Yatenga and founds a new capital. His call to the surrounding chiefs gives the town its name.",
         "Lasting power is built by bringing people together, not only by giving orders."),
     scenes=[
         scene(art("dusk", "sahel", it("rider", 30), it("horse", 46, s=0.9), it("baobab", 80, 26, 0.9), it("bird-small", 60, 50)),
               "Au XVIIIᵉ siècle, le royaume mossi du Yatenga était déchiré. Le jeune prince Kango, dont le nom signifie « lion », avait dû fuir son pays et vivre longtemps en exil, loin des siens.",
               "In the 18th century, the Mossi kingdom of Yatenga was torn apart. The young prince Kango, whose name means \"lion\", had been forced to flee and live in exile for a long time, far from his people."),
         scene(art("day", "savanna", it("sun", 80, 300), it("rider", 24), it("horse-run", 40, s=0.9), it("man-up", 62, c="#7C3109"), it("man-up", 74, c="#2F3E6B"), it("drum", 88)),
               "Un jour, Kango revint avec des guerriers fidèles. Il reprit le trône et devint Naaba Kango. Mais régner sur un royaume divisé était plus difficile que gagner une bataille.",
               "One day Kango returned with loyal warriors. He regained the throne and became Naaba Kango. But ruling a divided kingdom was harder than winning a battle.",
               choice(("Comment unir le royaume ?", "How can the kingdom be united?"),
                      [("Appeler tous les chefs auprès de lui", "Call all the chiefs to him"), ("Rester seul dans son palais", "Stay alone in his palace")], 0,
                      ("Naaba Kango choisit un lieu nouveau pour y réunir tout le Yatenga…", "Naaba Kango chose a new place to gather all of Yatenga…"))),
         scene(art("day", "village", it("sun", 84, 300), it("palace", 54, 34, 0.9), it("king-talk", 34, c="#2F3E6B"), it("man", 70, c="#7C3109"), it("man", 80)),
               "Il fit bâtir sa cour en un lieu nouveau et lança à tous les chefs coutumiers : « Ouahigouya ! » — « Venez vous prosterner ! », « venez faire allégeance ». Les chefs vinrent un à un saluer le roi.",
               "He had his court built in a new place and called out to all the customary chiefs: \"Ouahigouya!\" — \"Come and bow down!\", \"come and pledge allegiance\". One by one the chiefs came to greet the king."),
         scene(art("day", "village", it("sun", 16, 260), it("palace", 30, 34, 0.7), it("mosque", 62, 34, 0.7), it("woman", 78), it("child", 86), it("hut", 46, 26)),
               "C'est ainsi que naquit Ouahigouya, vers 1780. Elle est devenue la grande ville du nord du pays. Le roi du Yatenga y siège toujours, et l'on y raconte encore l'histoire du roi-lion.",
               "That is how Ouahigouya was born, around 1780. It has become the great city of the country's north. The king of Yatenga still sits there, and the story of the lion-king is still told."),
     ],
     quizzes=[
         quiz(("Que signifie le nom Kango ?", "What does the name Kango mean?"),
              [("Lion", "Lion"), ("Étoile", "Star"), ("Rivière", "River")], 0),
         quiz(("Que veut dire Ouahigouya ?", "What does Ouahigouya mean?"),
              [("Venez vous prosterner", "Come and bow down"), ("La ville du marché", "The market town"), ("Le grand arbre", "The great tree")], 0),
     ],
     glossary=[gloss("allégeance", "fr", "Promesse de fidélité et d'obéissance faite à un chef.", "A promise of loyalty and obedience made to a ruler.")],
     source=("Tradition rapportée par Naaba Kiiba, roi du Yatenga (Burkina24, « Ici au Faso »), Sidwaya et l'article Wikipédia « Naaba Kango ». Fondation vers 1780 selon les sources. Mise en récit libre.",
             "Tradition reported by Naaba Kiiba, king of Yatenga (Burkina24, \"Ici au Faso\"), Sidwaya and the Wikipedia article \"Naaba Kango\". Founded around 1780 according to the sources. Free retelling."))
